CREATE FUNCTION accounting.fn_assert_period_writable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_lock text;
  v_code text;
begin
  select lock_level, code into v_lock, v_code
    from accounting.fiscal_periods
   where id = new.fiscal_period_id;

  if v_lock = 'hard' then
    raise exception 'Fiscal period % is hard-locked; reopen it before posting', v_code
      using errcode = 'check_violation';
  end if;

  return new;
end $$;


