--
-- Name: fn_attachment_derive(); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_attachment_derive() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.content is not null then
    new.size_bytes := octet_length(new.content);
    new.sha256 := encode(digest(new.content, 'sha256'), 'hex');
  end if;
  return new;
end $$;


ALTER FUNCTION accounting.fn_attachment_derive() OWNER TO lsevin;

--
-- Name: fn_attachments_follow_entry(); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_attachments_follow_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
begin
  select status into v_status
    from accounting.journal_entries
   where id = coalesce(new.entry_id, old.entry_id);

  -- The entry is already gone when it cascades; let the cascade run.
  if v_status is null then
    return coalesce(new, old);
  end if;

  if accounting.fn_status_is_editable(v_status) then
    return coalesce(new, old);
  end if;

  -- Adding evidence to a document already in the books is allowed: a bank advice
  -- often arrives after the entry. Changing or removing what is there is not.
  if tg_op = 'INSERT' then
    return new;
  end if;

  raise exception
    'Attachments of a % document cannot be changed or removed', v_status
    using errcode = 'restrict_violation';
end $$;


ALTER FUNCTION accounting.fn_attachments_follow_entry() OWNER TO lsevin;

