--
-- Name: fn_block_ledger_mutation(); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_block_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_entry_status text;
begin
  if tg_op = 'UPDATE' and tg_table_name = 'journal_entries' then
    if accounting.fn_status_is_editable(old.status) then
      return new;
    end if;

    -- A committed document may still record its own supersession and the
    -- workflow stamps that go with it, but nothing financial.
    if to_jsonb(new) - 'reversed_by_entry_id' - 'status' - 'posted_at' - 'posted_by'
         - 'approved_at' - 'approved_by' - 'rejected_at' - 'rejected_by'
         - 'rejection_reason'
       = to_jsonb(old) - 'reversed_by_entry_id' - 'status' - 'posted_at' - 'posted_by'
         - 'approved_at' - 'approved_by' - 'rejected_at' - 'rejected_by'
         - 'rejection_reason'
       and new.status in ('approved', 'posted', 'reversed', 'rejected')
    then
      return new;
    end if;
  end if;

  if tg_table_name = 'journal_lines' then
    select status into v_entry_status
      from accounting.journal_entries
     where id = coalesce(new.entry_id, old.entry_id);

    -- The parent is already gone when an entry cascades away; let the cascade run.
    if v_entry_status is null then
      return coalesce(new, old);
    end if;

    if accounting.fn_status_is_editable(v_entry_status) then
      return coalesce(new, old);
    end if;
  end if;

  raise exception
    'accounting.% is append-only (attempted %). Correct a posted entry with a reversing entry.',
    tg_table_name, tg_op
    using errcode = 'restrict_violation';
end $$;


ALTER FUNCTION accounting.fn_block_ledger_mutation() OWNER TO lsevin;

--
-- Name: fn_consume_rate_limit(text, integer, integer); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_consume_rate_limit(p_bucket_key text, p_limit integer, p_window_secs integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
  v_window_start timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_secs) * p_window_secs);
  v_count        integer;
begin
  insert into accounting.rate_limits (bucket_key, window_start, request_count)
  values (p_bucket_key, v_window_start, 1)
  on conflict (bucket_key, window_start) do update
    set request_count = accounting.rate_limits.request_count + 1,
        updated_at = now()
  returning request_count into v_count;

  return v_count <= p_limit;
end $$;


ALTER FUNCTION accounting.fn_consume_rate_limit(p_bucket_key text, p_limit integer, p_window_secs integer) OWNER TO lsevin;

--
-- Name: fn_ensure_monthly_periods(uuid); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_ensure_monthly_periods(p_fiscal_year_id uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  v_year    record;
  v_month   date;
  v_starts  date;
  v_ends    date;
  v_code    text;
  v_created integer := 0;
begin
  select id, code, starts_on, ends_on into v_year
    from accounting.fiscal_years
   where id = p_fiscal_year_id;

  if v_year.id is null then
    raise exception 'Unknown fiscal year %', p_fiscal_year_id;
  end if;

  v_month := date_trunc('month', v_year.starts_on)::date;

  while v_month <= v_year.ends_on loop
    -- Clamp to the year's own bounds so a fiscal year that does not start on the
    -- first of a month gets a correct short first period rather than one that
    -- overlaps the previous year and trips the no-overlap exclusion constraint.
    v_starts := greatest(v_month, v_year.starts_on);
    v_ends   := least((v_month + interval '1 month - 1 day')::date, v_year.ends_on);
    v_code   := to_char(v_month, 'YYYY-MM');

    if not exists (
      select 1 from accounting.fiscal_periods
       where fiscal_year_id = v_year.id and code = v_code
    ) then
      insert into accounting.fiscal_periods (fiscal_year_id, code, starts_on, ends_on, status)
      values (v_year.id, v_code, v_starts, v_ends, 'open');
      v_created := v_created + 1;
    end if;

    v_month := (v_month + interval '1 month')::date;
  end loop;

  return v_created;
end $$;


ALTER FUNCTION accounting.fn_ensure_monthly_periods(p_fiscal_year_id uuid) OWNER TO lsevin;

--
-- Name: FUNCTION fn_ensure_monthly_periods(p_fiscal_year_id uuid); Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON FUNCTION accounting.fn_ensure_monthly_periods(p_fiscal_year_id uuid) IS 'Creates any missing monthly periods for a fiscal year. Idempotent. Call it when opening a new fiscal year.';


--
-- Name: fn_lines_before_insert(); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_lines_before_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_account accounting.accounts%rowtype;
  v_status  text;
begin
  select * into v_account from accounting.accounts where id = new.account_id;

  if not v_account.is_postable then
    raise exception 'Account % is not postable (postings belong on leaf accounts)', v_account.code
      using errcode = 'check_violation';
  end if;
  if not v_account.is_active then
    raise exception 'Account % is inactive', v_account.code using errcode = 'check_violation';
  end if;
  if v_account.currency_code is not null and v_account.currency_code <> new.currency_code then
    raise exception 'Account % only accepts %, got %', v_account.code, v_account.currency_code, new.currency_code
      using errcode = 'check_violation';
  end if;

  select p.status into v_status
    from accounting.journal_entries e
    join accounting.fiscal_periods p on p.id = e.fiscal_period_id
   where e.id = new.entry_id;

  if v_status = 'closed' then
    raise exception 'Fiscal period is closed; post to an open period or reopen it'
      using errcode = 'check_violation';
  end if;

  return new;
end $$;


ALTER FUNCTION accounting.fn_lines_before_insert() OWNER TO lsevin;

