-- Name: fn_recompute_wallet_balance(uuid, text); Type: FUNCTION; Schema: accounting; Owner: lsevin
--

CREATE FUNCTION accounting.fn_recompute_wallet_balance(p_wallet_id uuid, p_bucket text DEFAULT 'available'::text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  select coalesce(sum(
    case when direction = 'credit' then amount else -amount end
  ), 0)::numeric(38,18)
  from accounting.wallet_ledger
  where wallet_id = p_wallet_id
    and bucket = p_bucket;
$$;


