-- Name: prevent_customer_mobile_identity_update(); Type: FUNCTION; Schema: customer; Owner: lsevin
--

CREATE FUNCTION customer.prevent_customer_mobile_identity_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('lsevin.allow_mobile_identity_update', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF OLD.phone_number_country_code IS DISTINCT FROM NEW.phone_number_country_code
     OR OLD.phone_number IS DISTINCT FROM NEW.phone_number THEN
    RAISE EXCEPTION 'Customer mobile number is immutable. Use the verified mobile-change flow instead.'
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


