--
-- Name: set_bug_report_last_modified_date(); Type: FUNCTION; Schema: support; Owner: lsevin
--

CREATE FUNCTION support.set_bug_report_last_modified_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.last_modified_date = now();

  if new.status in ('resolved', 'closed', 'duplicate', 'wont_fix') and old.status is distinct from new.status then
    new.resolved_at = coalesce(new.resolved_at, now());
    if new.status = 'closed' then
      new.closed_at = coalesce(new.closed_at, now());
    end if;
  end if;

  if new.status = 'triaged' and old.status is distinct from 'triaged' then
    new.triaged_at = coalesce(new.triaged_at, now());
  end if;

  return new;
end;
$$;


ALTER FUNCTION support.set_bug_report_last_modified_date() OWNER TO lsevin;

