--
-- Name: touch_conversation_from_message(); Type: FUNCTION; Schema: support; Owner: lsevin
--

CREATE FUNCTION support.touch_conversation_from_message() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  update support.conversations
     set last_message_at = new.create_date,
         last_message_preview = left(coalesce(new.body, ''), 240),
         last_customer_message_at = case when new.sender_type = 'customer' and new.is_internal_note = false then new.create_date else last_customer_message_at end,
         last_agent_message_at = case when new.sender_type = 'agent' and new.is_internal_note = false then new.create_date else last_agent_message_at end,
         unread_for_admin_count = case when new.sender_type = 'customer' and new.is_internal_note = false then unread_for_admin_count + 1 else unread_for_admin_count end,
         unread_for_customer_count = case when new.sender_type = 'agent' and new.is_internal_note = false then unread_for_customer_count + 1 else unread_for_customer_count end,
         status = case when status in ('resolved', 'closed') and new.sender_type = 'customer' then 'open' else status end,
         last_modified_date = now()
   where id = new.conversation_id;
  return new;
end;
$$;


ALTER FUNCTION support.touch_conversation_from_message() OWNER TO lsevin;

