--
-- Name: v_account_balances_by_currency; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_account_balances_by_currency AS
 SELECT a.id AS account_id,
    a.code AS account_code,
    l.currency_code,
    COALESCE(sum(l.debit_amount), (0)::numeric) AS total_debit,
    COALESCE(sum(l.credit_amount), (0)::numeric) AS total_credit,
        CASE a.normal_balance
            WHEN 'debit'::text THEN (COALESCE(sum(l.debit_amount), (0)::numeric) - COALESCE(sum(l.credit_amount), (0)::numeric))
            ELSE (COALESCE(sum(l.credit_amount), (0)::numeric) - COALESCE(sum(l.debit_amount), (0)::numeric))
        END AS balance
   FROM ((accounting.accounts a
     JOIN accounting.journal_lines l ON ((l.account_id = a.id)))
     JOIN accounting.journal_entries e ON (((e.id = l.entry_id) AND (e.status = ANY (ARRAY['posted'::text, 'reversed'::text])))))
  GROUP BY a.id, a.code, a.normal_balance, l.currency_code;


ALTER VIEW accounting.v_account_balances_by_currency OWNER TO lsevin;

--
-- Name: v_trial_balance; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_trial_balance AS
 SELECT a.id AS account_id,
    a.code AS account_code,
    a.name_translations AS account_name,
    a.account_type,
    a.normal_balance,
    l.base_currency_code AS currency_code,
    COALESCE(sum(l.base_debit_amount), (0)::numeric) AS total_debit,
    COALESCE(sum(l.base_credit_amount), (0)::numeric) AS total_credit,
        CASE a.normal_balance
            WHEN 'debit'::text THEN (COALESCE(sum(l.base_debit_amount), (0)::numeric) - COALESCE(sum(l.base_credit_amount), (0)::numeric))
            ELSE (COALESCE(sum(l.base_credit_amount), (0)::numeric) - COALESCE(sum(l.base_debit_amount), (0)::numeric))
        END AS balance
   FROM (accounting.accounts a
     LEFT JOIN ( SELECT l_1.id,
            l_1.entry_id,
            l_1.line_no,
            l_1.account_id,
            l_1.party_type,
            l_1.party_id,
            l_1.wallet_id,
            l_1.wallet_bucket,
            l_1.currency_code,
            l_1.debit_amount,
            l_1.credit_amount,
            l_1.base_currency_code,
            l_1.base_debit_amount,
            l_1.base_credit_amount,
            l_1.exchange_rate,
            l_1.exchange_rate_id,
            l_1.rate_as_of,
            l_1.memo,
            l_1.metadata,
            l_1.cost_center_id,
            l_1.project_id,
            l_1.branch_id,
            l_1.department_id,
            l_1.cost_center_kind,
            l_1.project_kind,
            l_1.branch_kind,
            l_1.department_kind
           FROM (accounting.journal_lines l_1
             JOIN accounting.journal_entries e ON ((e.id = l_1.entry_id)))
          WHERE accounting.fn_status_is_in_books(e.status)) l ON ((l.account_id = a.id)))
  GROUP BY a.id, a.code, a.name_translations, a.account_type, a.normal_balance, l.base_currency_code;


ALTER VIEW accounting.v_trial_balance OWNER TO lsevin;

--
-- Name: v_balance_sheet; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_balance_sheet AS
 SELECT a.account_type,
    root.code AS group_code,
    root.name_translations AS group_name,
    tb.currency_code,
    sum(tb.balance) AS balance
   FROM ((accounting.v_trial_balance tb
     JOIN accounting.accounts a ON ((a.id = tb.account_id)))
     JOIN accounting.accounts root ON (((root.level = 1) AND ("left"(a.code, 1) = root.code))))
  WHERE (a.account_type = ANY (ARRAY['asset'::text, 'liability'::text, 'equity'::text]))
  GROUP BY a.account_type, root.code, root.name_translations, tb.currency_code;


ALTER VIEW accounting.v_balance_sheet OWNER TO lsevin;

--
-- Name: v_cost_center_report; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_cost_center_report AS
 SELECT d.id AS cost_center_id,
    d.code,
    d.name_translations,
    d.budget_amount,
    d.budget_currency,
    COALESCE(sum(l.base_debit_amount), (0)::numeric) AS total_debit,
    COALESCE(sum(l.base_credit_amount), (0)::numeric) AS total_credit,
    COALESCE(sum((l.base_debit_amount - l.base_credit_amount)), (0)::numeric) AS net_amount,
    count(DISTINCT l.entry_id) AS entry_count,
        CASE
            WHEN ((d.budget_amount IS NULL) OR (d.budget_amount = (0)::numeric)) THEN NULL::numeric
            ELSE round(((COALESCE(sum((l.base_debit_amount - l.base_credit_amount)), (0)::numeric) / d.budget_amount) * (100)::numeric), 2)
        END AS budget_used_percent
   FROM (accounting.dimensions d
     LEFT JOIN ( SELECT l_1.id,
            l_1.entry_id,
            l_1.line_no,
            l_1.account_id,
            l_1.party_type,
            l_1.party_id,
            l_1.wallet_id,
            l_1.wallet_bucket,
            l_1.currency_code,
            l_1.debit_amount,
            l_1.credit_amount,
            l_1.base_currency_code,
            l_1.base_debit_amount,
            l_1.base_credit_amount,
            l_1.exchange_rate,
            l_1.exchange_rate_id,
            l_1.rate_as_of,
            l_1.memo,
            l_1.metadata,
            l_1.cost_center_id,
            l_1.project_id,
            l_1.branch_id,
            l_1.department_id,
            l_1.cost_center_kind,
            l_1.project_kind,
            l_1.branch_kind,
            l_1.department_kind
           FROM (accounting.journal_lines l_1
             JOIN accounting.journal_entries e ON ((e.id = l_1.entry_id)))
          WHERE accounting.fn_status_is_in_books(e.status)) l ON ((l.cost_center_id = d.id)))
  WHERE (d.kind = 'cost_center'::text)
  GROUP BY d.id, d.code, d.name_translations, d.budget_amount, d.budget_currency;


ALTER VIEW accounting.v_cost_center_report OWNER TO lsevin;

--
-- Name: VIEW v_cost_center_report; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_cost_center_report IS 'Spend per cost centre against its budget. Only posted and reversed entries count.';


--
-- Name: v_currency_exposure; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_currency_exposure AS
 SELECT l.currency_code,
    sum(l.debit_amount) AS total_debit,
    sum(l.credit_amount) AS total_credit,
    sum((l.debit_amount - l.credit_amount)) AS net_amount,
    l.base_currency_code,
    sum((l.base_debit_amount - l.base_credit_amount)) AS net_base_amount,
    count(DISTINCT l.entry_id) AS entry_count
   FROM (accounting.journal_lines l
     JOIN accounting.journal_entries e ON ((e.id = l.entry_id)))
  WHERE accounting.fn_status_is_in_books(e.status)
  GROUP BY l.currency_code, l.base_currency_code;


ALTER VIEW accounting.v_currency_exposure OWNER TO lsevin;

--
-- Name: VIEW v_currency_exposure; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_currency_exposure IS 'Net position per currency, and its base-currency value at the posted rates.';


