    CONSTRAINT ck_wallet_transactions_signed_amount_matches_direction CHECK (((((direction)::text = 'credit'::text) AND (amount > (0)::numeric)) OR (((direction)::text = 'debit'::text) AND (amount < (0)::numeric)))),
    CONSTRAINT ck_wallet_transactions_status CHECK (((status)::text = ANY (ARRAY[('pending'::character varying)::text, ('processing'::character varying)::text, ('completed'::character varying)::text, ('failed'::character varying)::text, ('cancelled'::character varying)::text, ('refunded'::character varying)::text]))),
    CONSTRAINT ck_wallet_transactions_type CHECK (((transaction_type)::text = ANY (ARRAY[('topup'::character varying)::text, ('booking_payment'::character varying)::text, ('refund'::character varying)::text, ('cashback'::character varying)::text, ('referral_bonus'::character varying)::text, ('manual_adjustment'::character varying)::text, ('withdrawal'::character varying)::text])))
);


ALTER TABLE customer.wallet_transactions OWNER TO lsevin;

--
-- Name: v_legacy_wallet_balances; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_legacy_wallet_balances AS
 SELECT wa.user_id,
    wt.currency_code,
    sum(wt.amount) FILTER (WHERE ((wt.status)::text = 'completed'::text)) AS available_amount,
    sum(wt.amount) FILTER (WHERE ((wt.status)::text = ANY (ARRAY[('pending'::character varying)::text, ('processing'::character varying)::text]))) AS pending_amount,
    count(*) AS transaction_count
   FROM (customer.wallet_accounts wa
     JOIN customer.wallet_transactions wt ON ((wt.wallet_account_id = wa.id)))
  GROUP BY wa.user_id, wt.currency_code
 HAVING (sum(wt.amount) FILTER (WHERE ((wt.status)::text = 'completed'::text)) IS NOT NULL);


ALTER VIEW accounting.v_legacy_wallet_balances OWNER TO lsevin;

--
-- Name: VIEW v_legacy_wallet_balances; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_legacy_wallet_balances IS 'Per-user, per-currency balance as the legacy wallet computes it: sum of completed customer.wallet_transactions.';


--
-- Name: wallets; Type: TABLE; Schema: accounting; Owner: lsevin
