    pending_balance numeric(38,18) DEFAULT 0 NOT NULL,
    last_entry_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ck_wallets_available_non_negative CHECK ((available_balance >= (0)::numeric)),
    CONSTRAINT ck_wallets_pending_non_negative CHECK ((pending_balance >= (0)::numeric)),
    CONSTRAINT ck_wallets_reserved_non_negative CHECK ((reserved_balance >= (0)::numeric)),
    CONSTRAINT wallets_status_check CHECK ((status = ANY (ARRAY['active'::text, 'frozen'::text, 'closed'::text])))
);


ALTER TABLE accounting.wallets OWNER TO lsevin;

--
-- Name: currencies; Type: TABLE; Schema: finance; Owner: lsevin
--

CREATE TABLE finance.currencies (
    code character varying(10) NOT NULL,
