    native_name text,
    symbol text NOT NULL,
    decimal_digits smallint DEFAULT 2 NOT NULL,
    is_iso boolean DEFAULT true NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    is_display_enabled boolean DEFAULT true NOT NULL,
