    CONSTRAINT ck_finance_currencies_asset_class CHECK ((asset_class = ANY (ARRAY['fiat'::text, 'crypto'::text]))),
    CONSTRAINT ck_finance_currencies_code_nonempty CHECK (((length(btrim((code)::text)) >= 3) AND (length(btrim((code)::text)) <= 10))),
    CONSTRAINT ck_finance_currencies_decimal_digits CHECK (((decimal_digits >= 0) AND (decimal_digits <= 18)))
);


ALTER TABLE finance.currencies OWNER TO lsevin;

--
-- Name: v_cutover_exceptions; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_cutover_exceptions AS
 SELECT legacy.user_id,
    legacy.currency_code,
    legacy.available_amount AS legacy_balance,
    legacy.transaction_count,
        CASE
            WHEN (legacy.available_amount < (0)::numeric) THEN 'negative_legacy_balance'::text
            WHEN (c.code IS NULL) THEN 'currency_not_registered'::text
            WHEN (legacy.available_amount = (0)::numeric) THEN 'zero_balance'::text
            WHEN (w.id IS NULL) THEN 'not_imported'::text
            ELSE 'ok'::text
        END AS reason
   FROM ((accounting.v_legacy_wallet_balances legacy
     LEFT JOIN finance.currencies c ON (((c.code)::text = (legacy.currency_code)::text)))
     LEFT JOIN accounting.wallets w ON (((w.user_id = legacy.user_id) AND ((w.currency_code)::text = (legacy.currency_code)::text))))
  WHERE ((legacy.available_amount <= (0)::numeric) OR (c.code IS NULL) OR (w.id IS NULL));


ALTER VIEW accounting.v_cutover_exceptions OWNER TO lsevin;

--
-- Name: VIEW v_cutover_exceptions; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_cutover_exceptions IS 'Legacy wallet balances that were not imported into the ledger, with the reason. Review every row before treating the cut-over as complete.';


--
-- Name: v_cutover_reconciliation; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_cutover_reconciliation AS
 SELECT COALESCE(legacy.user_id, w.user_id) AS user_id,
    COALESCE(legacy.currency_code, w.currency_code) AS currency_code,
    COALESCE(legacy.available_amount, (0)::numeric) AS legacy_balance,
    COALESCE(w.available_balance, (0)::numeric) AS ledger_balance,
    (COALESCE(w.available_balance, (0)::numeric) - COALESCE(legacy.available_amount, (0)::numeric)) AS difference,
    (COALESCE(w.available_balance, (0)::numeric) = COALESCE(legacy.available_amount, (0)::numeric)) AS matches,
    legacy.transaction_count AS legacy_transaction_count,
    w.id AS wallet_id
   FROM (accounting.v_legacy_wallet_balances legacy
     FULL JOIN accounting.wallets w ON (((w.user_id = legacy.user_id) AND ((w.currency_code)::text = (legacy.currency_code)::text))));


ALTER VIEW accounting.v_cutover_reconciliation OWNER TO lsevin;

--
-- Name: VIEW v_cutover_reconciliation; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_cutover_reconciliation IS 'Legacy wallet balance vs accounting ledger balance, per user per currency. After cut-over every row must have matches = true.';


--
-- Name: v_entry_attachments; Type: VIEW; Schema: accounting; Owner: lsevin
