--
-- Name: v_income_statement; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_income_statement AS
 SELECT a.account_type,
    a.code AS account_code,
    a.name_translations AS account_name,
    tb.currency_code,
    sum(tb.balance) AS amount
   FROM (accounting.v_trial_balance tb
     JOIN accounting.accounts a ON ((a.id = tb.account_id)))
  WHERE (a.account_type = ANY (ARRAY['income'::text, 'expense'::text]))
  GROUP BY a.account_type, a.code, a.name_translations, tb.currency_code;


ALTER VIEW accounting.v_income_statement OWNER TO lsevin;

--
-- Name: v_ledger_entries; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_ledger_entries AS
 SELECT l.id AS line_id,
    e.id AS entry_id,
    e.entry_number,
    e.entry_date,
    e.status AS entry_status,
    e.source_type,
    e.source_id,
    e.description AS entry_description,
    e.fiscal_period_id,
    fp.code AS fiscal_period_code,
    a.id AS account_id,
    a.code AS account_code,
    a.name_translations AS account_name,
    a.account_type,
    a.normal_balance,
    l.line_no,
    l.party_type,
    l.party_id,
    l.wallet_id,
    l.currency_code,
    l.debit_amount,
    l.credit_amount,
    l.base_currency_code,
    l.base_debit_amount,
    l.base_credit_amount,
    l.exchange_rate,
    l.memo
   FROM (((accounting.journal_lines l
     JOIN accounting.journal_entries e ON ((e.id = l.entry_id)))
     JOIN accounting.accounts a ON ((a.id = l.account_id)))
     LEFT JOIN accounting.fiscal_periods fp ON ((fp.id = e.fiscal_period_id)))
  WHERE (e.status = ANY (ARRAY['posted'::text, 'reversed'::text]));


ALTER VIEW accounting.v_ledger_entries OWNER TO lsevin;

--
-- Name: v_opening_balance_suspense; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_opening_balance_suspense AS
 SELECT b.currency_code,
    b.total_debit AS imported_to_ledger,
    b.total_credit AS offset_by_real_assets,
    (b.total_debit - b.total_credit) AS unexplained_remainder
   FROM (accounting.v_account_balances_by_currency b
     JOIN accounting.accounts a ON ((a.id = b.account_id)))
  WHERE (a.system_key = 'opening_balance_equity'::text);


ALTER VIEW accounting.v_opening_balance_suspense OWNER TO lsevin;

--
-- Name: VIEW v_opening_balance_suspense; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_opening_balance_suspense IS 'Opening-balance suspense per currency. Drive unexplained_remainder to zero by recording the platform''s real asset balances.';


--
-- Name: v_party_balances; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_party_balances AS
 SELECT l.party_type,
    l.party_id,
    a.id AS account_id,
    a.code AS account_code,
    a.name_translations AS account_name,
    a.account_type,
    a.normal_balance,
    l.base_currency_code AS currency_code,
    sum(l.base_debit_amount) AS total_debit,
    sum(l.base_credit_amount) AS total_credit,
        CASE a.normal_balance
            WHEN 'debit'::text THEN sum((l.base_debit_amount - l.base_credit_amount))
            ELSE sum((l.base_credit_amount - l.base_debit_amount))
        END AS balance,
    count(*) AS line_count,
    max(e.entry_date) AS last_movement_at
   FROM ((accounting.journal_lines l
     JOIN accounting.journal_entries e ON ((e.id = l.entry_id)))
     JOIN accounting.accounts a ON ((a.id = l.account_id)))
  WHERE ((l.party_id IS NOT NULL) AND accounting.fn_status_is_in_books(e.status))
  GROUP BY l.party_type, l.party_id, a.id, a.code, a.name_translations, a.account_type, a.normal_balance, l.base_currency_code;


ALTER VIEW accounting.v_party_balances OWNER TO lsevin;

--
-- Name: VIEW v_party_balances; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_party_balances IS 'Per-party balance per account: provider payables, patient receivables, user wallets.';


