--
-- Name: v_period_coverage; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_period_coverage AS
 SELECT ( SELECT count(*) AS count
           FROM accounting.fiscal_periods
          WHERE ((CURRENT_DATE >= fiscal_periods.starts_on) AND (CURRENT_DATE <= fiscal_periods.ends_on) AND (fiscal_periods.status = 'open'::text) AND (fiscal_periods.lock_level <> 'hard'::text))) AS open_periods_today,
    ( SELECT max(fiscal_periods.ends_on) AS max
           FROM accounting.fiscal_periods
          WHERE (fiscal_periods.status = 'open'::text)) AS covered_until,
    GREATEST((( SELECT max(fiscal_periods.ends_on) AS max
           FROM accounting.fiscal_periods
          WHERE (fiscal_periods.status = 'open'::text)) - CURRENT_DATE), 0) AS days_of_runway;


ALTER VIEW accounting.v_period_coverage OWNER TO lsevin;

--
-- Name: VIEW v_period_coverage; Type: COMMENT; Schema: accounting; Owner: lsevin
--

COMMENT ON VIEW accounting.v_period_coverage IS 'Whether the ledger can accept a posting dated today, and how far ahead periods exist.';


--
-- Name: v_project_report; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_project_report AS
 SELECT d.id AS project_id,
    d.code,
    d.name_translations,
    d.budget_amount,
    d.starts_on,
    d.ends_on,
    COALESCE(sum(l.base_debit_amount), (0)::numeric) AS total_debit,
    COALESCE(sum(l.base_credit_amount), (0)::numeric) AS total_credit,
    COALESCE(sum((l.base_debit_amount - l.base_credit_amount)), (0)::numeric) AS net_amount,
    count(DISTINCT l.entry_id) AS entry_count
   FROM (accounting.dimensions d
     LEFT JOIN ( SELECT l_1.id,
            l_1.entry_id,
            l_1.line_no,
            l_1.account_id,
            l_1.party_type,
            l_1.party_id,
            l_1.wallet_id,
            l_1.wallet_bucket,
            l_1.currency_code,
            l_1.debit_amount,
            l_1.credit_amount,
            l_1.base_currency_code,
            l_1.base_debit_amount,
            l_1.base_credit_amount,
            l_1.exchange_rate,
            l_1.exchange_rate_id,
            l_1.rate_as_of,
            l_1.memo,
            l_1.metadata,
            l_1.cost_center_id,
            l_1.project_id,
            l_1.branch_id,
            l_1.department_id,
            l_1.cost_center_kind,
            l_1.project_kind,
            l_1.branch_kind,
            l_1.department_kind
           FROM (accounting.journal_lines l_1
             JOIN accounting.journal_entries e ON ((e.id = l_1.entry_id)))
          WHERE accounting.fn_status_is_in_books(e.status)) l ON ((l.project_id = d.id)))
  WHERE (d.kind = 'project'::text)
  GROUP BY d.id, d.code, d.name_translations, d.budget_amount, d.starts_on, d.ends_on;


ALTER VIEW accounting.v_project_report OWNER TO lsevin;

