    description text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT wallet_ledger_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT wallet_ledger_bucket_check CHECK ((bucket = ANY (ARRAY['available'::text, 'reserved'::text, 'pending'::text]))),
    CONSTRAINT wallet_ledger_direction_check CHECK ((direction = ANY (ARRAY['credit'::text, 'debit'::text]))),
    CONSTRAINT wallet_ledger_movement_type_check CHECK ((movement_type = ANY (ARRAY['deposit'::text, 'withdrawal'::text, 'withdrawal_hold'::text, 'withdrawal_release'::text, 'booking_payment'::text, 'refund'::text, 'cashback'::text, 'referral_bonus'::text, 'platform_fee'::text, 'adjustment'::text, 'reversal'::text, 'opening_balance'::text])))
);


ALTER TABLE accounting.wallet_ledger OWNER TO lsevin;

--
-- Name: v_user_statement; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_user_statement AS
 SELECT w.user_id,
    w.id AS wallet_id,
    w.currency_code,
    wl.seq,
    wl.occurred_at,
    wl.movement_type,
    wl.direction,
    wl.amount,
    wl.balance_after,
    wl.description,
    wl.reference_type,
    wl.reference_id,
    e.entry_number,
    e.id AS entry_id
   FROM ((accounting.wallet_ledger wl
     JOIN accounting.wallets w ON ((w.id = wl.wallet_id)))
     JOIN accounting.journal_entries e ON ((e.id = wl.entry_id)));


ALTER VIEW accounting.v_user_statement OWNER TO lsevin;

--
-- Name: v_wallet_balance_drift; Type: VIEW; Schema: accounting; Owner: lsevin
--

CREATE VIEW accounting.v_wallet_balance_drift AS
 SELECT wallet_id,
    user_id,
    currency_code,
    bucket,
    cached_balance,
    ledger_balance,
    drift
   FROM ( SELECT w.id AS wallet_id,
            w.user_id,
            w.currency_code,
            b.bucket,
            b.cached_balance,
            accounting.fn_recompute_wallet_balance(w.id, b.bucket) AS ledger_balance,
            (b.cached_balance - accounting.fn_recompute_wallet_balance(w.id, b.bucket)) AS drift
           FROM (accounting.wallets w
             CROSS JOIN LATERAL ( VALUES ('available'::text,w.available_balance), ('reserved'::text,w.reserved_balance), ('pending'::text,w.pending_balance)) b(bucket, cached_balance))) d
  WHERE (drift <> (0)::numeric);


ALTER VIEW accounting.v_wallet_balance_drift OWNER TO lsevin;

