    service_provider_id uuid NOT NULL,
    service_entity_type text DEFAULT 'provider'::text NOT NULL,
    service_entity_id uuid,
    locale text DEFAULT 'fa-IR'::text NOT NULL,
    offer_type text DEFAULT 'custom'::text NOT NULL,
    title text NOT NULL,
    description text NOT NULL,
    customer_promise text DEFAULT ''::text NOT NULL,
    eligibility text,
    terms text,
    cta_label text DEFAULT 'Request this offer'::text NOT NULL,
    cta_href text,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    total_slots integer,
    claimed_slots integer DEFAULT 0 NOT NULL,
    remaining_slots integer GENERATED ALWAYS AS (
CASE
    WHEN (total_slots IS NULL) THEN NULL::integer
    ELSE GREATEST((total_slots - claimed_slots), 0)
END) STORED,
    status text DEFAULT 'submitted'::text NOT NULL,
    moderation_note text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    published_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT conversion_offers_check CHECK (((ends_at IS NULL) OR (starts_at IS NULL) OR (ends_at > starts_at))),
    CONSTRAINT conversion_offers_claimed_slots_check CHECK ((claimed_slots >= 0)),
    CONSTRAINT conversion_offers_offer_type_check CHECK ((offer_type = ANY (ARRAY['free_consultation'::text, 'package'::text, 'limited_slot'::text, 'seasonal_offer'::text, 'deposit_bonus'::text, 'vip_followup'::text, 'custom'::text]))),
