--
-- Name: provider_daily_report_view; Type: VIEW; Schema: provider_portal; Owner: lsevin
--

CREATE VIEW provider_portal.provider_daily_report_view AS
 SELECT b.provider_id AS service_provider_id,
    (date_trunc('day'::text, b.create_date))::date AS report_date,
    COALESCE(max((cl.payment_currency_code)::text), max((b.currency_code)::text), 'USD'::text) AS currency_code,
    (count(DISTINCT b.id))::integer AS bookings_count,
    (COALESCE(sum(cl.payment_gross_amount), (0)::numeric))::numeric(18,2) AS gross_revenue,
    (COALESCE(sum(cl.net_amount), (0)::numeric))::numeric(18,2) AS net_revenue,
    (COALESCE(sum(cl.provider_payable_amount), (0)::numeric))::numeric(18,2) AS provider_payable_amount,
    (COALESCE(sum(rl.payment_refund_amount), (0)::numeric))::numeric(18,2) AS refunded_amount
   FROM ((booking.bookings b
     LEFT JOIN commercial.booking_charge_lines cl ON (((cl.booking_id = b.id) AND (cl.provider_id = b.provider_id))))
     LEFT JOIN commercial.refund_lines rl ON ((rl.booking_id = b.id)))
  WHERE (b.provider_id IS NOT NULL)
  GROUP BY b.provider_id, ((date_trunc('day'::text, b.create_date))::date);


ALTER VIEW provider_portal.provider_daily_report_view OWNER TO lsevin;

--
-- Name: provider_finance_kpis; Type: VIEW; Schema: provider_portal; Owner: lsevin
--

CREATE VIEW provider_portal.provider_finance_kpis AS
 SELECT sp.id AS service_provider_id,
    COALESCE(max((cl.payment_currency_code)::text), max((pl.currency_code)::text), 'USD'::text) AS currency_code,
    (COALESCE(sum(cl.payment_gross_amount), (0)::numeric))::numeric(18,2) AS gross_revenue,
    (COALESCE(sum(cl.net_amount), (0)::numeric))::numeric(18,2) AS net_revenue,
    (COALESCE(sum(cl.platform_fee_amount), (0)::numeric))::numeric(18,2) AS platform_fee_amount,
    (COALESCE(sum(cl.provider_payable_amount), (0)::numeric))::numeric(18,2) AS provider_payable_amount,
    (COALESCE(sum(rl.payment_refund_amount), (0)::numeric))::numeric(18,2) AS refunded_amount,
    (count(DISTINCT b.id))::integer AS bookings_count,
    (count(DISTINCT b.id) FILTER (WHERE (lower((COALESCE(b.payment_status, ''::character varying))::text) = ANY (ARRAY['paid'::text, 'captured'::text, 'succeeded'::text]))))::integer AS paid_bookings_count,
    (COALESCE(sum(pl.amount) FILTER (WHERE (pl.status = 'pending'::text)), (0)::numeric))::numeric(18,2) AS pending_ledger_amount,
    (COALESCE(sum(pl.amount) FILTER (WHERE (pl.status = 'approved'::text)), (0)::numeric))::numeric(18,2) AS approved_ledger_amount,
    (COALESCE(sum(abs(pl.amount)) FILTER (WHERE ((pl.status = 'paid'::text) OR (pl.entry_type = 'payout'::text))), (0)::numeric))::numeric(18,2) AS paid_ledger_amount
   FROM ((((category.service_providers sp
     LEFT JOIN booking.bookings b ON ((b.provider_id = sp.id)))
     LEFT JOIN commercial.booking_charge_lines cl ON (((cl.booking_id = b.id) AND (cl.provider_id = sp.id))))
     LEFT JOIN commercial.refund_lines rl ON ((rl.booking_id = b.id)))
     LEFT JOIN commercial.provider_ledgers pl ON ((pl.provider_id = sp.id)))
  GROUP BY sp.id;


ALTER VIEW provider_portal.provider_finance_kpis OWNER TO lsevin;

