    CONSTRAINT support_messages_body_or_attachment CHECK (((NULLIF(btrim(COALESCE(body, ''::text)), ''::text) IS NOT NULL) OR (jsonb_array_length(attachments) > 0) OR (message_type = 'system'::text))),
    CONSTRAINT support_messages_json_shapes CHECK (((jsonb_typeof(body_json) = 'object'::text) AND (jsonb_typeof(attachments) = 'array'::text) AND (jsonb_typeof(metadata) = 'object'::text))),
    CONSTRAINT support_messages_message_type CHECK ((message_type = ANY (ARRAY['text'::text, 'image'::text, 'file'::text, 'system'::text, 'note'::text]))),
    CONSTRAINT support_messages_sender_type CHECK ((sender_type = ANY (ARRAY['customer'::text, 'agent'::text, 'system'::text])))
);


ALTER TABLE support.messages OWNER TO lsevin;

--
-- Name: bug_report_admin_cards; Type: VIEW; Schema: support; Owner: lsevin
--

CREATE VIEW support.bug_report_admin_cards AS
 SELECT br.id,
    br.conversation_id,
    br.report_number,
    br.title,
    br.description,
    br.source_area,
    br.source_url,
    br.status,
    br.priority,
    br.severity,
    br.assigned_to_user_id,
    br.customer_user_id,
    br.guest_name,
    br.guest_email,
    br.create_date,
    br.last_modified_date,
    br.resolved_at,
    c.conversation_number,
    c.unread_for_admin_count,
    c.last_message_preview,
    c.last_message_at,
    (COALESCE(media_counts.media_count, (0)::bigint))::integer AS media_count,
    (COALESCE(message_counts.message_count, (0)::bigint))::integer AS message_count
   FROM (((support.bug_reports br
     JOIN support.conversations c ON ((c.id = br.conversation_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS media_count
           FROM support.bug_report_media m
          WHERE (m.bug_report_id = br.id)) media_counts ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS message_count
           FROM support.messages msg
          WHERE ((msg.conversation_id = br.conversation_id) AND (msg.deleted_at IS NULL))) message_counts ON (true))
  WHERE (br.deleted_at IS NULL);


ALTER VIEW support.bug_report_admin_cards OWNER TO lsevin;

