--
-- Name: v_pending_documents _RETURN; Type: RULE; Schema: accounting; Owner: lsevin
--

CREATE OR REPLACE VIEW accounting.v_pending_documents AS
 SELECT e.id,
    e.entry_number,
    e.entry_date,
    e.reference_number,
    e.description,
    e.entry_type,
    e.status,
    e.is_manual,
    e.created_by,
    e.created_at,
    e.approved_by,
    COALESCE(sum(l.base_debit_amount), (0)::numeric) AS total_debit,
    COALESCE(sum(l.base_credit_amount), (0)::numeric) AS total_credit,
    (COALESCE(sum(l.base_debit_amount), (0)::numeric) - COALESCE(sum(l.base_credit_amount), (0)::numeric)) AS difference,
    (COALESCE(sum(l.base_debit_amount), (0)::numeric) <> COALESCE(sum(l.base_credit_amount), (0)::numeric)) AS is_unbalanced,
    count(l.id) AS line_count,
    (CURRENT_DATE - (e.entry_date)::date) AS age_days
   FROM (accounting.journal_entries e
     LEFT JOIN accounting.journal_lines l ON ((l.entry_id = e.id)))
  WHERE (NOT accounting.fn_status_is_in_books(e.status))
  GROUP BY e.id;


